3	/**
4	 * The derived duplicate-detection identity of an owner: a single key that consolidates the
5	 * telephone, email and household the create pipeline rejects duplicates by. The key is
6	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}.
7	 *
8	 * <p>Two owners are duplicates only when their <em>whole</em> keys are equal, so members of
9	 * one household (same household id) with different telephones have different keys and are both
10	 * allowed — only an exact full-key match is a duplicate.
11	 */
12	public final class OwnerIdentity {
13	
14	    private OwnerIdentity() {
15	    }
16	
17	    /**
18	     * The identity key for the given canonical components. The telephone is compared in its
19	     * {@link OwnerTelephone#toE164(String) E.164} form and the email in its
20	     * {@link OwnerEmail#normalize(String) lower-cased} form; an absent email or household id
21	     * contributes the empty string.
22	     */
23	    public static String key(String telephone, String email, String householdId) {
24	        return normalizedTelephone(telephone) + "|" + normalizedEmail(email) + "|" + orEmpty(householdId);
25	    }
26	
27	    private static String normalizedTelephone(String telephone) {
28	        return OwnerTelephone.toE164(telephone).orElse(orEmpty(telephone));
29	    }
30	
31	    private static String normalizedEmail(String email) {
32	        return (email == null || email.isBlank()) ? "" : OwnerEmail.normalize(email);
33	    }
34	
35	    private static String orEmpty(String value) {
36	        return value == null ? "" : value;
37	    }
38	}
