3	import java.util.Map;
4	
5	/**
6	 * Fixed city-to-region lookup. Maps a small set of known cities to their canonical
7	 * region (locality) code; every other city resolves to {@link #UNKNOWN}.
8	 */
9	public final class CityRegion {
10	
11	    /** Region returned for any city not present in the {@link #TABLE table}. */
12	    public static final String UNKNOWN = "UNKNOWN";
13	
14	    /** The pinned city-to-region table. */
15	    private static final Map<String, String> TABLE = Map.of(
16	            "Sydney", "NSW",
17	            "Melbourne", "VIC",
18	            "Brisbane", "QLD");
19	
20	    private CityRegion() {
21	    }
22	
23	    /**
24	     * The canonical region for the given city, or {@link #UNKNOWN} when the city is not in
25	     * the table (including a null city).
26	     */
27	    public static String locality(String city) {
28	        return city == null ? UNKNOWN : TABLE.getOrDefault(city, UNKNOWN);
29	    }
30	}
