36	        return owner.getLastName() + ", " + owner.getFirstName();
37	    }
38	
39	    /** The upper-cased first letters of firstName and lastName, dot-separated with a
40	     *  trailing dot, e.g. 'J.S.'. */
41	    default String initials(Owner owner) {
42	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
43	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
44	    }
