62	     *  falling back to the fixed city-to-region table when the postcode is absent or in no
63	     *  known range, or 'UNKNOWN' when neither resolves a region. */
64	    default String locality(Owner owner) {
65	        String byPostcode = PostcodeRange.regionForPostcode(owner.getPostcode());
